use std::{fs,path::Path};
use atlas_core::design::{SelectedDesign,DesignState,AuthorityMode,DESIGN_SCHEMA_VERSION,container_candidate,design_identity};
use atlas_core::codara::construction::{ConstructionModule,SelfReconstructionReport,module_identity,report_identity,CheckResult};
fn main(){
 let args:Vec<_>=std::env::args().collect();
 let base=Path::new(&args[1]);
 let (atlas,root)=runtime::design::read_container(base.join("source.atlas")).unwrap();
 let mut design=SelectedDesign{schema:DESIGN_SCHEMA_VERSION.into(),design_id:String::new(),parent_root:root.clone(),candidate:container_candidate(&atlas),scope:"owned-source-fixture".into(),target_kind:"RUST".into(),variant:"unselected".into(),state:DesignState::Candidate,roots:vec![],bindings:vec![],candidate_set:vec![],evidence_refs:vec![],authority_mode:AuthorityMode::HumanRequired,authority_event:None,rationale:"Unselected source-only workflow; never Chronica admission".into(),supersedes:None,comparison:None};
 design.design_id=design_identity(&design);
 if args.len()==2{fs::write(base.join("model.json"),serde_json::to_vec_pretty(&runtime::agent::world_model(base.join("repo")).unwrap()).unwrap()).unwrap();fs::write(base.join("design.json"),serde_json::to_vec_pretty(&design).unwrap()).unwrap();println!("{}",serde_json::json!({"root":root,"design_id":design.design_id,"state":"CANDIDATE","authority":false}));return;}
 let module:ConstructionModule=serde_json::from_slice(&fs::read(base.join("attempt/module.json")).unwrap()).unwrap();
 let report:SelfReconstructionReport=serde_json::from_slice(&fs::read(base.join("attempt/report.json")).unwrap()).unwrap();
 let expected=runtime::self_reconstruction::lift(&atlas.typed_records,&root,"core/src/lib.rs","Mode",&design.design_id,None).unwrap();
 assert_eq!(module,expected);assert_eq!(module.module_id,module_identity(&module));assert_eq!(report.report_id,report_identity(&report));
 assert!(runtime::self_reconstruction::validate(&atlas,&module,&report).is_empty());
 assert!(report.gaps.is_empty());assert!(report.checks.iter().all(|c|c.result==CheckResult::Equivalent));assert!(!report.checks.is_empty());
 assert_eq!(report.design_state,DesignState::Candidate);assert!(report.shadow.is_some());assert!(!report.oracle_uses.is_empty());
 let emission=atlas_core::codara::construction::rust::emit(&expected);
 assert_eq!(fs::read_to_string(base.join("attempt/shadow.rs.txt")).unwrap(),emission.source);
 assert_eq!(runtime::self_reconstruction::declared_variations(&atlas.typed_records,&module,&emission),report.declared_variations);
 println!("{}",serde_json::json!({"status":"PASS","module_id":module.module_id,"report_id":report.report_id,"root":root,"verdict":report.verdict,"checks":report.checks.len(),"gaps":report.gaps.len(),"design_state":report.design_state,"oracle_uses":report.oracle_uses,"shadow":report.shadow,"full_module_matches_historical_lift":true,"scope":"Actual source fixture offline compiler caller; unselected and not target/rights/nativeV1 admission"}));
}

